from django.utils import timezone


def ajouter_un_mois(jour):
    import calendar

    annee, mois = (jour.year + 1, 1) if jour.month == 12 else (jour.year, jour.month + 1)
    return jour.replace(year=annee, month=mois, day=min(jour.day, calendar.monthrange(annee, mois)[1]))


def abonnements_existants(apps, schema_editor):
    Tenant = apps.get_model("tenants", "Tenant")
    Abonnement = apps.get_model("tenants", "Abonnement")
    Paiement = apps.get_model("tenants", "Paiement")
    aujourd_hui = timezone.localdate()
    for tenant in Tenant.objects.all():
        Abonnement.objects.get_or_create(tenant=tenant, defaults={
            "montant_mensuel": settings.PRIX_ABONNEMENT_FCFA,
            "date_debut": timezone.localdate(tenant.date_creation),
            "date_fin": ajouter_un_mois(aujourd_hui),
        })
    for paiement in Paiement.objects.filter(demande__tenant__isnull=False):
        paiement.tenant_id = paiement.demande.tenant_id
        paiement.save(update_fields=["tenant"])


